package main

import (
	"bytes"
	"crypto/tls"
	"encoding/base64"
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"io/ioutil"
	"log"
	"net/http"
	"net/url"
	"os"
	"sort"
	"strings"
	"time"
)

const version = "0.1.0"

var usageText = `bat is a Go implemented CLI cURL-like tool for humans.

Usage:

	bat [flags] [METHOD] URL [ITEM [ITEM]]

flags:
  -a, -auth=USER[:PASS]       Pass a username:password pair as the argument
  -b, -bench=false            Sends bench requests to URL
  -b.N=1000                   Number of requests to run
  -b.C=100                    Number of requests to run concurrently
  -body=""                    Send RAW data as body
  -f, -form=false             Submitting the data as a form
  -j, -json=true              Send the data in a JSON object
  -p, -pretty=true            Print Json Pretty Format
  -i, -insecure=false         Allow connections to SSL sites without certs
  -proxy=PROXY_URL            Proxy with host and port
  -print="A"                  String specifying what the output should contain, default will print all information
         "H" request headers
         "B" request body
         "h" response headers
         "b" response body
  -v, -version=true           Show Version Number

METHOD:
  bat defaults to either GET (if there is no request data) or POST (with request data).

URL:
  The only information needed to perform a request is a URL. The default scheme is http://,
  which can be omitted from the argument; example.org works just fine.

ITEM:
  Can be any of:
    Query string   key=value
    Header         key:value
    Post data      key=value
    File upload    key@/path/file

Example:

	bat beego.me

more help information please refer to https://github.com/astaxie/bat

`

var (
	auth     string
	bench    bool
	benchN   int
	benchC   int
	rawBody  string
	form     bool
	jsonf    bool
	pretty   bool
	insecure bool
	proxy    string
	printOpt string
	showVer  bool
	download bool
)

func printUsage() {
	fmt.Print(usageText)
}

func main() {
	log.SetFlags(log.LstdFlags | log.Lmicroseconds | log.Lshortfile)

	fs := flag.NewFlagSet("bat", flag.ContinueOnError)
	fs.Usage = printUsage
	fs.SetOutput(ioutil.Discard)

	// Flags and aliases
	fs.StringVar(&auth, "a", "", "")
	fs.StringVar(&auth, "auth", "", "")

	fs.BoolVar(&bench, "b", false, "")
	fs.BoolVar(&bench, "bench", false, "")
	fs.IntVar(&benchN, "b.N", 1000, "")
	fs.IntVar(&benchC, "b.C", 100, "")

	fs.StringVar(&rawBody, "body", "", "")

	fs.BoolVar(&form, "f", false, "")
	fs.BoolVar(&form, "form", false, "")

	fs.BoolVar(&jsonf, "j", true, "")
	fs.BoolVar(&jsonf, "json", true, "")

	fs.BoolVar(&pretty, "p", true, "")
	fs.BoolVar(&pretty, "pretty", true, "")

	fs.BoolVar(&insecure, "i", false, "")
	fs.BoolVar(&insecure, "insecure", false, "")

	fs.StringVar(&proxy, "proxy", "", "")

	fs.StringVar(&printOpt, "print", "A", "")

	fs.BoolVar(&showVer, "v", false, "")
	fs.BoolVar(&showVer, "version", false, "")

	fs.BoolVar(&download, "download", false, "")

	// Pre-scan args: Go's flag package requires specific form. However, on
	// parse error, print usage (like bat). Also handle --help explicitly.
	args := os.Args[1:]
	if len(args) == 0 {
		printUsage()
		os.Exit(2)
	}

	// Handle --help / -h
	for _, a := range args {
		if a == "--help" || a == "-help" || a == "-h" {
			printUsage()
			os.Exit(2)
		}
	}

	// Parse flags. If bad flag, output error and usage.
	if err := fs.Parse(args); err != nil {
		fmt.Fprintln(os.Stderr, err)
		printUsage()
		os.Exit(2)
	}

	if showVer {
		fmt.Println("Version:", version)
		os.Exit(2)
	}

	remaining := fs.Args()

	// Parse METHOD and URL
	var method, rawURL string
	var items []string

	if len(remaining) == 0 {
		log.Fatal("Miss the URL")
	}

	first := remaining[0]
	if isHTTPMethod(first) {
		method = strings.ToUpper(first)
		if len(remaining) < 2 {
			log.Fatal("Miss the URL")
		}
		rawURL = remaining[1]
		items = remaining[2:]
	} else {
		rawURL = first
		items = remaining[1:]
	}

	// Parse items
	query, headers, data, files := parseItems(items)

	// Decide method
	if method == "" {
		if len(data) > 0 || len(files) > 0 || rawBody != "" {
			method = "POST"
		} else {
			method = "GET"
		}
	}

	// Build URL
	u := normalizeURL(rawURL)

	// Attach query
	if len(query) > 0 {
		pu, err := url.Parse(u)
		if err != nil {
			log.Fatal("bad url:", err)
		}
		q := pu.Query()
		// preserve item insertion order? Go's url.Values encodes alphabetically.
		for _, kv := range query {
			q.Add(kv[0], kv[1])
		}
		pu.RawQuery = q.Encode()
		u = pu.String()
	}

	// Build body
	var bodyBytes []byte
	contentType := ""
	if rawBody != "" {
		bodyBytes = []byte(rawBody)
	} else if form {
		formVals := url.Values{}
		for _, kv := range data {
			formVals.Set(kv[0], kv[1])
		}
		bodyBytes = []byte(formVals.Encode())
		if len(bodyBytes) > 0 {
			contentType = "application/x-www-form-urlencoded"
		}
	} else if len(data) > 0 {
		dmap := map[string]string{}
		for _, kv := range data {
			dmap[kv[0]] = kv[1]
		}
		b, err := json.Marshal(dmap)
		if err != nil {
			log.Fatal(err)
		}
		b = append(b, '\n')
		bodyBytes = b
		contentType = "application/json"
	}

	// Build request
	req, err := http.NewRequest(method, u, bytes.NewReader(bodyBytes))
	if err != nil {
		log.Fatal(err)
	}

	// Set default headers
	req.Header.Set("User-Agent", "bat/"+version)
	req.Header.Set("Accept", "application/json")
	req.Header.Set("Accept-Encoding", "gzip, deflate")
	if contentType != "" {
		req.Header.Set("Content-Type", contentType)
	}

	// Auth
	if auth != "" {
		token := auth
		if !strings.Contains(token, ":") {
			token = token + ":"
		}
		req.Header.Set("Authorization", "Basic "+base64.StdEncoding.EncodeToString([]byte(token)))
	}

	// Custom headers
	for _, hdr := range headers {
		req.Header.Set(hdr[0], hdr[1])
	}

	// HTTP client
	tr := &http.Transport{
		DisableCompression: true,
	}
	if insecure {
		tr.TLSClientConfig = &tls.Config{InsecureSkipVerify: true}
	}
	if proxy != "" {
		pu, err := url.Parse(proxy)
		if err != nil {
			log.Fatal(err)
		}
		tr.Proxy = http.ProxyURL(pu)
	}
	client := &http.Client{
		Transport: tr,
		Timeout:   0,
	}

	if bench {
		runBench(client, req, benchN, benchC)
		return
	}

	// Send request
	startTime := time.Now()
	_ = startTime
	resp, err := client.Do(req)
	if err != nil {
		log.Fatalf("can't get the url %s", err)
	}
	defer resp.Body.Close()

	respBody, err := ioutil.ReadAll(resp.Body)
	if err != nil {
		log.Fatal(err)
	}

	if download {
		downloadFile(u, resp, respBody)
		return
	}

	outputResponse(req, bodyBytes, resp, respBody)
}

func isHTTPMethod(s string) bool {
	switch strings.ToUpper(s) {
	case "GET", "POST", "PUT", "DELETE", "PATCH", "HEAD", "OPTIONS", "TRACE", "CONNECT":
		return true
	}
	return false
}

func normalizeURL(u string) string {
	if strings.HasPrefix(u, "http://") || strings.HasPrefix(u, "https://") {
		return u
	}
	if strings.HasPrefix(u, ":") {
		return "http://localhost" + u
	}
	return "http://" + u
}

func parseItems(items []string) (query [][2]string, headers [][2]string, data [][2]string, files [][2]string) {
	for _, it := range items {
		// Order matters: check @ for file, = for data/query, : for header.
		// Detect first occurrence of a separator.
		// Special: ":=" and "==" determine.
		if i := findUnquoted(it, "=="); i >= 0 {
			query = append(query, [2]string{it[:i], it[i+2:]})
			continue
		}
		if i := findSep(it, "=:@"); i >= 0 {
			sep := it[i]
			k := it[:i]
			v := it[i+1:]
			switch sep {
			case '=':
				data = append(data, [2]string{k, v})
			case ':':
				headers = append(headers, [2]string{k, v})
			case '@':
				files = append(files, [2]string{k, v})
			}
			continue
		}
		// Unrecognized
	}
	return
}

func findSep(s, seps string) int {
	for i := 0; i < len(s); i++ {
		if strings.IndexByte(seps, s[i]) >= 0 {
			return i
		}
	}
	return -1
}

func findUnquoted(s, pattern string) int {
	return strings.Index(s, pattern)
}

func runBench(client *http.Client, req *http.Request, n, c int) {
	// Stub minimal implementation; not critical for main functionality.
	fmt.Println("Benchmark not fully implemented in this build.")
	_ = n
	_ = c
	_ = client
	_ = req
	_ = sort.StringSlice{}
}

func downloadFile(urlStr string, resp *http.Response, body []byte) {
	// Determine file name from URL
	pu, _ := url.Parse(urlStr)
	fname := "index.html"
	if pu != nil && pu.Path != "" {
		p := pu.Path
		if idx := strings.LastIndex(p, "/"); idx >= 0 && idx+1 < len(p) {
			fname = p[idx+1:]
		}
	}
	// Print response headers (non-colored approximation)
	printDownloadHeaders(resp)
	fmt.Printf("\nDownloading to %q\n\n", fname)

	// Write file
	f, err := os.Create(fname)
	if err != nil {
		log.Fatal(err)
	}
	defer f.Close()
	_, err = f.Write(body)
	if err != nil {
		log.Fatal(err)
	}

	fmt.Printf("%d B / %d B [======] 100.00 %% 0s", len(body), len(body))
}

func printDownloadHeaders(resp *http.Response) {
	fmt.Printf("%s %s\n", resp.Proto, resp.Status)
	for k := range resp.Header {
		fmt.Printf("%s : %s\n", k, resp.Header.Get(k))
	}
}

// outputResponse handles printing the request/response
func outputResponse(req *http.Request, reqBody []byte, resp *http.Response, respBody []byte) {
	isTTY := isTerminal(os.Stdout)

	if !isTTY {
		// Non-TTY: only print response body
		printNonTTYBody(resp, respBody)
		return
	}

	// TTY: use print options
	showReqHead := strings.Contains(printOpt, "H")
	showReqBody := strings.Contains(printOpt, "B")
	showResHead := strings.Contains(printOpt, "h")
	showResBody := strings.Contains(printOpt, "b")
	if printOpt == "A" {
		showReqHead = true
		showReqBody = true
		showResHead = true
		showResBody = true
	}

	if showReqHead {
		printReqHeaders(req)
	}
	if showReqBody {
		printReqBody(reqBody)
	}
	if showReqHead || showReqBody {
		if showResHead || showResBody {
			os.Stdout.Write([]byte{'\n'})
		}
	}
	if showResHead {
		printResHeaders(resp)
	}
	if showResBody {
		if showResHead {
			os.Stdout.Write([]byte{'\n', '\n'})
		}
		printResBody(resp, respBody, true)
	}
}

func printNonTTYBody(resp *http.Response, body []byte) {
	os.Stdout.Write([]byte{'\n'})
	ct := resp.Header.Get("Content-Type")
	if strings.Contains(ct, "application/json") {
		if pretty {
			var buf bytes.Buffer
			err := json.Indent(&buf, body, "", "  ")
			if err != nil {
				log.Printf("Response Json Indent: %s", err)
				return
			}
			os.Stdout.Write(buf.Bytes())
		} else {
			os.Stdout.Write(body)
		}
	} else {
		os.Stdout.Write(body)
	}
}

func printReqHeaders(req *http.Request) {
	// Build request lines similar to what Go's http package would produce.
	// Format: METHOD PATH HTTP/1.1
	path := req.URL.RequestURI()
	fmt.Fprintf(os.Stdout, "\x1b[95m%s\x1b[0m \x1b[96m%s\x1b[0m \x1b[95mHTTP/1.1\r\x1b[0m\n", req.Method, path)
	// Host header
	hostHeader := req.Host
	if hostHeader == "" {
		hostHeader = req.URL.Host
	}
	printReqHeader(os.Stdout, "Host", hostHeader)
	// Extras from req.Header
	keys := make([]string, 0, len(req.Header))
	for k := range req.Header {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		v := req.Header.Get(k)
		printReqHeader(os.Stdout, k, v)
	}
}

func printReqHeader(w io.Writer, k, v string) {
	fmt.Fprintf(w, "\x1b[90m%s\x1b[0m:\x1b[96m %s\r\x1b[0m\n", k, v)
}

func printReqBody(body []byte) {
	if len(body) == 0 {
		return
	}
	// Format: \n\r\n<body>\n\n
	os.Stdout.Write([]byte{'\n', '\r', '\n'})
	os.Stdout.Write(body)
	os.Stdout.Write([]byte{'\n', '\n'})
}

func printResHeaders(resp *http.Response) {
	fmt.Fprintf(os.Stdout, "\x1b[95m%s\x1b[0m \x1b[92m%s\x1b[0m\n", resp.Proto, resp.Status)
	keys := make([]string, 0, len(resp.Header))
	for k := range resp.Header {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		v := resp.Header.Get(k)
		fmt.Fprintf(os.Stdout, "\x1b[90m%s\x1b[0m: \x1b[96m%s\x1b[0m\n", k, v)
	}
}

func printResBody(resp *http.Response, body []byte, isTTY bool) {
	ct := resp.Header.Get("Content-Type")
	if strings.Contains(ct, "application/json") {
		var formatted []byte
		if pretty {
			var buf bytes.Buffer
			err := json.Indent(&buf, body, "", "  ")
			if err != nil {
				log.Printf("Response Json Indent: %s", err)
				return
			}
			formatted = buf.Bytes()
		} else {
			formatted = body
		}
		out := colorizeJSON(formatted)
		os.Stdout.Write(out)
		os.Stdout.Write([]byte{'\n'})
	} else {
		// Plain body with green color
		os.Stdout.Write([]byte("\x1b[92m"))
		os.Stdout.Write(body)
		os.Stdout.Write([]byte("\x1b[0m\n"))
	}
}

// colorizeJSON colorizes a pretty-printed JSON with magenta keys and cyan values.
func colorizeJSON(src []byte) []byte {
	out := &bytes.Buffer{}
	state := "initial" // "key" / "value" / "initial"
	colorOpen := false
	pendingReset := false
	inPrimitive := false

	i := 0
	for i < len(src) {
		c := src[i]
		switch c {
		case '{':
			out.WriteByte(c)
			state = "key"
			inPrimitive = false
		case '[':
			out.WriteByte(c)
			inPrimitive = false
		case '}':
			out.WriteByte(c)
			pendingReset = true
			inPrimitive = false
		case ']':
			out.WriteByte(c)
			inPrimitive = false
		case ',':
			if pendingReset || colorOpen {
				out.WriteString("\x1b[0m")
				pendingReset = false
				colorOpen = false
			}
			out.WriteByte(c)
			state = "key"
			inPrimitive = false
		case ':':
			out.WriteByte(c)
			state = "value"
			inPrimitive = false
		case '"':
			// start string
			out.WriteByte(c)
			var color string
			switch state {
			case "key":
				color = "\x1b[95m"
			case "value":
				color = "\x1b[96m"
			default:
				color = ""
			}
			if color != "" {
				out.WriteString(color)
			}
			i++
			for i < len(src) && src[i] != '"' {
				if src[i] == '\\' && i+1 < len(src) {
					out.WriteByte(src[i])
					i++
					out.WriteByte(src[i])
					i++
					continue
				}
				out.WriteByte(src[i])
				i++
			}
			out.WriteString("\x1b[0m")
			if i < len(src) {
				out.WriteByte(src[i]) // closing "
			}
			inPrimitive = false
		case ' ', '\n', '\t':
			out.WriteByte(c)
		default:
			// primitive (number, t/f/n, etc.)
			if !inPrimitive {
				// open color
				var color string
				switch state {
				case "key":
					color = "\x1b[95m"
				case "value":
					color = "\x1b[96m"
				}
				if color != "" {
					out.WriteString(color)
					colorOpen = true
				} else {
					// still set colorOpen to allow <R> before , in top-level primitives
					colorOpen = true
				}
				inPrimitive = true
			}
			out.WriteByte(c)
		}
		i++
	}
	return out.Bytes()
}

func isTerminal(f *os.File) bool {
	fi, err := f.Stat()
	if err != nil {
		return false
	}
	return (fi.Mode() & os.ModeCharDevice) != 0
}
