	os.Stdout.Write([]byte{'\n', '\r', '\n'})
	os.Stdout.Write(body)
	os.Stdout.Write([]byte{'\n', '\n'})
}

func printResHeaders(resp *http.Response) {
	fmt.Fprintf(os.Stdout, "\x1b[95m%s\x1b[0m \x1b[92m%s\x1b[0m\n", resp.Proto, resp.Status)
	keys := make([]string, 0, len(resp.Header))
	for k := range resp.Header {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		v := resp.Header.Get(k)
		fmt.Fprintf(os.Stdout, "\x1b[90m%s\x1b[0m: \x1b[96m%s\x1b[0m\n", k, v)
