func printResBody(resp *http.Response, body []byte, isTTY bool) {
	ct := resp.Header.Get("Content-Type")
	if strings.Contains(ct, "application/json") {
		var formatted []byte
		if pretty {
			var buf bytes.Buffer
			err := json.Indent(&buf, body, "", "  ")
			if err != nil {
