		}
		out := colorizeJSON(formatted)
		os.Stdout.Write(out)
		os.Stdout.Write([]byte{'\n'})
	} else {
		// Plain body with green color
		os.Stdout.Write([]byte("\x1b[92m"))
		os.Stdout.Write(body)
		os.Stdout.Write([]byte("\x1b[0m\n"))
	}
}

// colorizeJSON colorizes a pretty-printed JSON with magenta keys and cyan values.
func colorizeJSON(src []byte) []byte {
	out := &bytes.Buffer{}
	state := "initial" // "key" / "value" / "initial"
	colorOpen := false
	pendingReset := false
	inPrimitive := false

	i := 0
	for i < len(src) {
		c := src[i]
		switch c {
		case '{':
			out.WriteByte(c)
			state = "key"
			inPrimitive = false
		case '[':
			out.WriteByte(c)
			inPrimitive = false
		case '}':
			out.WriteByte(c)
			pendingReset = true
			inPrimitive = false
		case ']':
			out.WriteByte(c)
			inPrimitive = false
		case ',':
			if pendingReset || colorOpen {
				out.WriteString("\x1b[0m")
				pendingReset = false
				colorOpen = false
			}
			out.WriteByte(c)
			state = "key"
			inPrimitive = false
		case ':':
			out.WriteByte(c)
			state = "value"
			inPrimitive = false
		case '"':
			// start string
			out.WriteByte(c)
			var color string
			switch state {
			case "key":
				color = "\x1b[95m"
			case "value":
				color = "\x1b[96m"
			default:
				color = ""
			}
			if color != "" {
				out.WriteString(color)
			}
			i++
			for i < len(src) && src[i] != '"' {
				if src[i] == '\\' && i+1 < len(src) {
					out.WriteByte(src[i])
					i++
					out.WriteByte(src[i])
					i++
					continue
				}
				out.WriteByte(src[i])
				i++
			}
			out.WriteString("\x1b[0m")
			if i < len(src) {
				out.WriteByte(src[i]) // closing "
			}
			inPrimitive = false
		case ' ', '\n', '\t':
			out.WriteByte(c)
		default:
			// primitive (number, t/f/n, etc.)
			if !inPrimitive {
				// open color
				var color string
				switch state {
				case "key":
					color = "\x1b[95m"
				case "value":
					color = "\x1b[96m"
				}
				if color != "" {
					out.WriteString(color)
					colorOpen = true
				} else {
					// still set colorOpen to allow <R> before , in top-level primitives
					colorOpen = true
				}
				inPrimitive = true
			}
			out.WriteByte(c)
		}
		i++
	}
	return out.Bytes()
}

func isTerminal(f *os.File) bool {
	fi, err := f.Stat()
	if err != nil {
		return false
	}
	return (fi.Mode() & os.ModeCharDevice) != 0
}
