package main

// http.go encapsulates everything related to formatting the
// response bytes into human friendly output. It handles:
//   * distinguishing JSON and non-JSON bodies based on Content-Type
//   * pretty-printing JSON with colour annotations in a TTY
//   * emitting the dump of the request / response in TTY mode

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"sort"
	"strings"
)

// outputResponse picks between the TTY and non-TTY rendering paths
// depending on whether standard output is connected to a terminal.
func outputResponse(req *http.Request, reqBody []byte, resp *http.Response, respBody []byte) {
	if isTerminal(os.Stdout) {
		outputTTY(req, reqBody, resp, respBody)
		return
	}
	outputNonTTY(resp, respBody)
}

// outputTTY emits colourised request and response sections. The
// set of sections shown is controlled by the `-print` flag.
func outputTTY(req *http.Request, reqBody []byte, resp *http.Response, respBody []byte) {
	showReqHead, showReqBody, showResHead, showResBody := expandPrint(printOpt)
	w := os.Stdout
	if showReqHead {
		writeReqHeaders(w, req)
	}
	if showReqBody {
		writeReqBody(w, reqBody)
	}
	if (showReqHead || showReqBody) && (showResHead || showResBody) {
		w.Write([]byte{'\n'})
	}
	if showResHead {
		writeResHeaders(w, resp)
	}
	if showResBody {
		if showResHead {
			w.Write([]byte{'\n', '\n'})
		}
		writeResBody(w, resp, respBody)
	}
}

// outputNonTTY writes only the response body, pretty-printed when
// the content is JSON and the -pretty flag is on.
func outputNonTTY(resp *http.Response, body []byte) {
	os.Stdout.Write([]byte{'\n'})
	ct := resp.Header.Get("Content-Type")
	if strings.Contains(ct, "application/json") {
		if pretty {
			var buf bytes.Buffer
			err := json.Indent(&buf, body, "", "  ")
			// A clear error message is surfaced if the payload is
			// not a valid JSON document: the indent call rejects
			// malformed input up front.
			if err != nil {
				// The format of this log message matches the
				// historical behaviour of bat when a body is
				// advertised as JSON but cannot be parsed.
				//
				log.Printf("Response Json Indent: %s", err)
				return
			}
			os.Stdout.Write(buf.Bytes())
			return
		}
		os.Stdout.Write(body)
		return
	}
	os.Stdout.Write(body)
}

// expandPrint converts the string value of the -print flag into
// four boolean toggles corresponding to the request/response,
// headers/body portions. The special string "A" selects every
// section.
func expandPrint(p string) (reqHead, reqBody, resHead, resBody bool) {
	if p == "A" {
		return true, true, true, true
	}
	return strings.Contains(p, "H"), strings.Contains(p, "B"), strings.Contains(p, "h"), strings.Contains(p, "b")
}

// writeReqHeaders emits the request line and the request headers in
// the compact, colourised form that bat uses when printing to a
// terminal.  The trailing \r before each newline mimics the wire
// representation produced by Go's http.Request.Write method.
func writeReqHeaders(w io.Writer, req *http.Request) {
	path := req.URL.RequestURI()
	fmt.Fprintf(w, "\x1b[95m%s\x1b[0m \x1b[96m%s\x1b[0m \x1b[95mHTTP/1.1\r\x1b[0m\n", req.Method, path)
	hostHeader := req.Host
	if hostHeader == "" {
		hostHeader = req.URL.Host
	}
	writeReqHeader(w, "Host", hostHeader)
	keys := make([]string, 0, len(req.Header))
	for k := range req.Header {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		writeReqHeader(w, k, req.Header.Get(k))
	}
}

// writeReqHeader is the single-line helper used by writeReqHeaders.
func writeReqHeader(w io.Writer, k, v string) {
	fmt.Fprintf(w, "\x1b[90m%s\x1b[0m:\x1b[96m %s\r\x1b[0m\n", k, v)
}

// writeReqBody renders the body that was sent with the outgoing
// request.  The surrounding `\r\n` and trailing double newline mimic
// the on-the-wire CRLF between headers and body.
func writeReqBody(w io.Writer, body []byte) {
	if len(body) == 0 {
		return
	}
	w.Write([]byte{'\n', '\r', '\n'})
	w.Write(body)
	w.Write([]byte{'\n', '\n'})
}

// writeResHeaders emits the response status line followed by the
// response headers.  Iteration over resp.Header is intentionally
// unordered so that the output matches the randomised map iteration
// order that Go's runtime provides.
func writeResHeaders(w io.Writer, resp *http.Response) {
	fmt.Fprintf(w, "\x1b[95m%s\x1b[0m \x1b[92m%s\x1b[0m\n", resp.Proto, resp.Status)
	for k, vs := range resp.Header {
		v := ""
		if len(vs) > 0 {
			v = vs[0]
		}
		fmt.Fprintf(w, "\x1b[90m%s\x1b[0m: \x1b[96m%s\x1b[0m\n", k, v)
	}
}

// writeResBody renders the response body in the TTY.  For JSON
// payloads the body is first re-indented (preserving key order) and
// then colourised; other payloads are written verbatim wrapped in a
// green envelope.
func writeResBody(w io.Writer, resp *http.Response, body []byte) {
	ct := resp.Header.Get("Content-Type")
	if strings.Contains(ct, "application/json") {
		var formatted []byte
		if pretty {
			var buf bytes.Buffer
			err := json.Indent(&buf, body, "", "  ")
			if err != nil {
				log.Printf("Response Json Indent: %s", err)
				return
			}
			formatted = buf.Bytes()
		} else {
			formatted = body
		}
		out := colorizeJSON(formatted)
		w.Write(out)
		w.Write([]byte{'\n'})
		return
	}
	w.Write([]byte("\x1b[92m"))
	w.Write(body)
	w.Write([]byte("\x1b[0m\n"))
}

// isTerminal reports whether the provided file descriptor is
// connected to a character device, ie a terminal.
func isTerminal(f *os.File) bool {
	fi, err := f.Stat()
	if err != nil {
		return false
	}
	return (fi.Mode() & os.ModeCharDevice) != 0
}
GOEOF
