	"os"
	"strings"
)

// downloadFile writes the response body to disk and prints a small
// progress summary line that matches the layout produced by the
// original bat binary.
func downloadFile(urlStr string, resp *http.Response, body []byte) {
	fname := "index.html"
	if pu, err := url.Parse(urlStr); err == nil && pu.Path != "" {
		p := pu.Path
		if idx := strings.LastIndex(p, "/"); idx >= 0 && idx+1 < len(p) {
			fname = p[idx+1:]
		}
	}
	printDownloadHeaders(resp)
	fmt.Printf("\nDownloading to %q\n\n", fname)
	f, err := os.Create(fname)
	if err != nil {
		log.Fatal(err)
	}
	defer f.Close()
	if _, err := f.Write(body); err != nil {
		log.Fatal(err)
	}
	fmt.Printf("%d B / %d B [======] 100.00 %% 0s", len(body), len(body))
}

// printDownloadHeaders emits the response status and headers in the
// format expected by download mode (key : value with a space before
// the colon, slightly different from the standard header renderer).
