package main

// colorize.go contains the JSON colouriser used when emitting a
// response body to a terminal. The algorithm is a single pass
// state machine that wraps string values in cyan, string keys in
// magenta, and primitives in whichever colour matches the parser's
// current expectation (key vs value).
//
// The behaviour faithfully follows the quirks of the original
// implementation: after a comma the parser moves into "key" state
// regardless of whether we are actually inside an array.  The
// observable side-effect of that choice is that subsequent
// elements in an array are coloured magenta instead of cyan.

import (
	"bytes"
)

// colorizeJSON walks through a (pretty printed) JSON byte slice
// and returns a copy with ANSI colour escapes applied.
func colorizeJSON(src []byte) []byte {
	out := &bytes.Buffer{}

	state := "initial" // either "key", "value" or "initial"
	colorOpen := false
	pendingReset := false
	inPrimitive := false

	i := 0
	for i < len(src) {
		c := src[i]
		switch c {
		case '{':
			out.WriteByte(c)
			state = "key"
			inPrimitive = false
		case '[':
			out.WriteByte(c)
			inPrimitive = false
		case '}':
			out.WriteByte(c)
			pendingReset = true
			inPrimitive = false
		case ']':
			out.WriteByte(c)
			inPrimitive = false
		case ',':
			if pendingReset || colorOpen {
				out.WriteString("\x1b[0m")
				pendingReset = false
				colorOpen = false
			}
			out.WriteByte(c)
			state = "key"
			inPrimitive = false
		case ':':
			out.WriteByte(c)
			state = "value"
			inPrimitive = false
		case '"':
			out.WriteByte(c)
			switch state {
			case "key":
				out.WriteString("\x1b[95m")
			case "value":
				out.WriteString("\x1b[96m")
			}
			i++
			for i < len(src) && src[i] != '"' {
				if src[i] == '\\' && i+1 < len(src) {
					out.WriteByte(src[i])
					i++
					out.WriteByte(src[i])
					i++
					continue
				}
				out.WriteByte(src[i])
				i++
			}
			out.WriteString("\x1b[0m")
			if i < len(src) {
				out.WriteByte(src[i])
			}
			inPrimitive = false
		case ' ', '\n', '\t':
			out.WriteByte(c)
		default:
			if !inPrimitive {
				switch state {
				case "key":
					out.WriteString("\x1b[95m")
				case "value":
					out.WriteString("\x1b[96m")
				}
				colorOpen = true
				inPrimitive = true
			}
			out.WriteByte(c)
		}
		i++
	}
	return out.Bytes()
}
GOEOF

