	defer f.Close()
	if _, err := f.Write(body); err != nil {
		log.Fatal(err)
	}
	fmt.Printf("%d B / %d B [======] 100.00 %% 0s", len(body), len(body))
}

// printDownloadHeaders emits the response status and headers in the
// format expected by download mode (key : value with a space before
// the colon, slightly different from the standard header renderer).
