// buildQuery appends the ordered query pairs to an optional existing
// RawQuery string. Values are URL-encoded. The function preserves the
// order of the `pairs` slice as they were provided.
func buildQuery(existing string, pairs [][2]string) string {
	var sb strings.Builder
	if existing != "" {
		sb.WriteString(existing)
	}
	for _, kv := range pairs {
		if sb.Len() > 0 {
			sb.WriteByte('&')
		}
		sb.WriteString(queryEscape(kv[0]))
		sb.WriteByte('=')
		sb.WriteString(queryEscape(kv[1]))
	}
	return sb.String()
}

// queryEscape URL-encodes a string for use in a query parameter.
func queryEscape(s string) string {
	// Use net/url's QueryEscape semantics.
	// (lazy-imported via url.QueryEscape in callers)
	return urlQueryEscape(s)
}
