package main

// bench.go - HTTP benchmark mode.  Produces a concise summary,
// status code distribution, a simple histogram and latency
// percentiles.  The output shape matches the original bat binary
// so existing scripts keep working.

import (
	"fmt"
	"io"
	"io/ioutil"
	"net/http"
	"sort"
	"sync"
	"time"
)

// runBench executes `n` requests spread across `c` concurrent
// workers and prints a summary table once all workers complete.
func runBench(client *http.Client, req *http.Request, n, c int) {
	if n <= 0 {
		n = 1000
	}
	if c <= 0 {
		c = 100
	}
	if c > n {
		c = n
	}

	type result struct {
		duration time.Duration
		status   int
		size     int64
		err      error
	}
	results := make([]result, n)
	jobs := make(chan int, n)
	for i := 0; i < n; i++ {
		jobs <- i
	}
	close(jobs)

	var wg sync.WaitGroup
	wg.Add(c)
	overallStart := time.Now()
	for w := 0; w < c; w++ {
		go func() {
			defer wg.Done()
			for idx := range jobs {
				reqCopy := req.Clone(req.Context())
				start := time.Now()
				resp, err := client.Do(reqCopy)
				var size int64
				status := 0
				if err == nil {
					status = resp.StatusCode
					size, _ = io.Copy(ioutil.Discard, resp.Body)
					resp.Body.Close()
				}
				results[idx] = result{duration: time.Since(start), status: status, size: size, err: err}
			}
		}()
	}
	wg.Wait()
	total := time.Since(overallStart)

	durations := make([]float64, 0, n)
	statusCounts := map[int]int{}
	var dataTotal int64
	var slowest, fastest time.Duration
	var sumDur time.Duration
	for _, r := range results {
		if r.err != nil {
			continue
		}
		d := r.duration
		sumDur += d
		durations = append(durations, d.Seconds())
		if d > slowest {
			slowest = d
		}
		if fastest == 0 || d < fastest {
			fastest = d
		}
		statusCounts[r.status]++
		dataTotal += r.size
	}
	sort.Float64s(durations)

	fmt.Printf("\nSummary:\n")
	fmt.Printf("  Total:\t%.4f secs.\n", total.Seconds())
	fmt.Printf("  Slowest:\t%.4f secs.\n", slowest.Seconds())
	fmt.Printf("  Fastest:\t%.4f secs.\n", fastest.Seconds())
	if len(durations) > 0 {
		fmt.Printf("  Average:\t%.4f secs.\n", sumDur.Seconds()/float64(len(durations)))
		fmt.Printf("  Requests/sec:\t%.4f\n", float64(len(durations))/total.Seconds())
	}
	if dataTotal > 0 {
		fmt.Printf("  Total Data Received:\t%d bytes.\n", dataTotal)
		fmt.Printf("  Response Size per Request:\t%d bytes.\n", dataTotal/int64(len(durations)))
	}

	fmt.Println()
	fmt.Println("Status code distribution:")
	codes := make([]int, 0, len(statusCounts))
	for k := range statusCounts {
		codes = append(codes, k)
	}
	sort.Ints(codes)
	for _, k := range codes {
		fmt.Printf("  [%d]\t%d responses\n", k, statusCounts[k])
	}

	if len(durations) == 0 {
		return
	}

	fmt.Println()
	fmt.Println("Response time histogram:")
	const buckets = 11
	lo := durations[0]
	hi := durations[len(durations)-1]
	step := (hi - lo) / float64(buckets-1)
	if step == 0 {
		step = 1e-6
	}
	counts := make([]int, buckets)
	for _, d := range durations {
		idx := int((d - lo) / step)
		if idx < 0 {
			idx = 0
		}
		if idx >= buckets {
			idx = buckets - 1
		}
		counts[idx]++
	}
	maxCount := 0
	for _, cnt := range counts {
		if cnt > maxCount {
			maxCount = cnt
		}
	}
	for i, cnt := range counts {
		bound := lo + step*float64(i)
		bar := ""
		if maxCount > 0 {
			scale := 40 * cnt / maxCount
			for k := 0; k < scale; k++ {
				bar += "\u220e"
			}
		}
		fmt.Printf("  %.3f [%d]\t|%s\n", bound, cnt, bar)
	}

	fmt.Println()
	fmt.Println("Latency distribution:")
	percs := []int{10, 25, 50, 75, 90, 95, 99}
	for _, p := range percs {
		idx := p * len(durations) / 100
		if idx >= len(durations) {
			idx = len(durations) - 1
		}
		fmt.Printf("  %d%% in %.4f secs.\n", p, durations[idx])
	}
}
GOEOF

