		if cnt > maxCount {
			maxCount = cnt
		}
	}
	for i, cnt := range counts {
		bound := lo + step*float64(i)
		bar := ""
		if maxCount > 0 {
			scale := 40 * cnt / maxCount
			for k := 0; k < scale; k++ {
				bar += "\u220e"
			}
		}
		fmt.Printf("  %.3f [%d]\t|%s\n", bound, cnt, bar)
	}

	fmt.Println()
	fmt.Println("Latency distribution:")
	percs := []int{10, 25, 50, 75, 90, 95, 99}
	for _, p := range percs {
		idx := p * len(durations) / 100
		if idx >= len(durations) {
			idx = len(durations) - 1
		}
		fmt.Printf("  %d%% in %.4f secs.\n", p, durations[idx])
	}
}
